def f(grid):
    from collections import Counter, deque
    cnt=Counter(v for r in grid for v in r)
    bg=cnt.most_common(1)[0][0]
    h,w=len(grid),len(grid[0])
    seen=set(); comps=[]
    for i in range(h):
        for j in range(w):
            if grid[i][j]!=bg and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); comp=[]
                while q:
                    a,b=q.popleft(); comp.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<w and grid[x][y]!=bg and (x,y) not in seen:
                            seen.add((x,y)); q.append((x,y))
                comps.append(comp)
    tmpl=max(comps,key=len)
    rs=[a for a,b in tmpl]; cs=[b for a,b in tmpl]
    cr,cc=(min(rs)+max(rs))//2,(min(cs)+max(cs))//2
    tvals={(a-min(rs),b-min(cs)):grid[a][b] for a,b in tmpl}
    th,tw=max(rs)-min(rs)+1,max(cs)-min(cs)+1
    out=[row[:] for row in grid]
    for comp in comps:
        if comp is tmpl: continue
        a,b=comp[0]
        top,left=a-cr,b-cc  # place template so its center is at marker
        for (dr,dc),v in tvals.items():
            x,y=top+dr,left+dc
            if 0<=x<h and 0<=y<w: out[x][y]=v
    return out
